const VERSION = "0.4.0+45c425bd";
const MIN_CLAUDE = [2, 1, 295];
const DEFAULT_UPDATE_BASE = 'https://raw.githubusercontent.com/BobTheHobo/claude-usage-dashboard/main/'; // latest.json + this installer
