const HELP = `Claude Code usage dashboard installer ${VERSION}

  node install-usage-dashboard.js              install (or reinstall this version)
  node install-usage-dashboard.js --update     fetch and install the newest published version
  node install-usage-dashboard.js --open       ... and open the report afterwards
  node install-usage-dashboard.js --uninstall  remove it (your data in ~/.claude/usage-report is kept)
  node install-usage-dashboard.js --uninstall --purge   ... and delete that data too
  node install-usage-dashboard.js --dry-run    show what would happen, change nothing (works with the above)
  node install-usage-dashboard.js --sync <git-url>   (advanced) share usage between your computers via a git repo
  node install-usage-dashboard.js --no-sync    turn sharing off (default)
  node install-usage-dashboard.js --help       this text

Needs Node.js 18+ and Claude Code 2.1.295+. After installing, start a NEW Claude Code session and type /usage-report.`;

// A background update (--result-file) reports how it ended in a small file the add-on reads; it also removes its own
// temp copy (update-<pid>.js in the scripts folder) so nothing is left behind.
let resultFile = null;
function finish(result) {
  try {
    if (resultFile) writeAtomic(resultFile, JSON.stringify({ ...result, version: VERSION, at: new Date().toISOString() }) + '\n');
  } catch (_) { /* the add-on then simply hears nothing */ }
  try {
    if (/^update-\d+\.js$/.test(path.basename(__filename)) && same(path.dirname(__filename), appDir)) fs.rmSync(__filename, { force: true });
  } catch (_) { /* a leftover temp file is swept by the next install */ }
}
function fail(msg) { finish({ ok: false, error: maskSecrets(String(msg).split('\n')[0]).slice(0, 300) }); console.error(msg); process.exit(1); }

// Credentials in a git URL (or a git error) never reach the screen. Same patterns as tools/usage-report/sync.js.
const maskSecrets = (s) => String(s || '')
  .replace(/(\w+:\/\/)[^/@\s]+@/g, '$1***@')
  .replace(/\b(gh[pousr]_[A-Za-z0-9]{10,}|github_pat_[A-Za-z0-9_]{10,})\b/g, '***')
  .replace(/(authorization:\s*(?:bearer|basic)\s+)\S+/gi, '$1***');

// A file that is locked or not writable (EBUSY, EPERM, ...) ends with one plain line, not a stack trace.
// Anything else is reported the same way to a background update's result file (the add-on would otherwise hear nothing).
function fatal(e) {
  if (e && e.syscall && typeof e.code === 'string') fail(`Could not update ${e.dest || e.path || 'a file'} (${e.code}). Close Claude Code and run this again.`);
  console.error(e && e.stack || String(e));
  finish({ ok: false, error: maskSecrets(String((e && e.message) || e).split('\n')[0]).slice(0, 300) });
  process.exit(1);
}
process.on('uncaughtException', fatal);

if (Number(process.versions.node.split('.')[0]) < 18) fail(`This installer needs Node.js 18 or newer (you have ${process.versions.node}). Install a newer Node from https://nodejs.org and run it again.`);

// ---- arguments
// A URL (https://...) or scp-style remote (git@host:path, host:path; a single letter before the colon is a Windows
// drive) is kept as typed; anything else is a folder, stored absolute (the sync runs from another working directory).
function normalizeRemote(v) {
  if (/^\w+:\/\//.test(v) || /^(?:[^@\s/\\]+@[^\s/\\:]+|[^\s/\\:@]{2,}):/.test(v)) return v;
  return path.resolve(/^~(?=$|[\\/])/.test(v) ? os.homedir() + v.slice(1) : v);
}

const argv = process.argv.slice(2);
const flag = (name) => argv.includes(name);
const known = new Set(['--help', '-h', '--dry-run', '--uninstall', '--purge', '--open', '--no-sync', '--sync', '--update', '--background', '--no-smoke', '--result-file', '--release']);
