const say = (m) => console.log((dry ? '[dry-run] ' : '') + m);

// ---- helpers
function writeAtomic(file, text) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const tmp = `${file}.tmp-${process.pid}`;
  try { fs.writeFileSync(tmp, text); fs.renameSync(tmp, file); }
  catch (e) { try { fs.rmSync(tmp, { force: true }); } catch (_) { /* nothing to clean */ } throw e; }
}

// Parsed JSON object from a file: {} when the file is missing, null (and a message) when it is not a JSON object.
function readJson(file) {
  let text;
  try { text = fs.readFileSync(file, 'utf8'); } catch (e) { if (e.code === 'ENOENT') return { exists: false, data: {} }; throw e; }
  text = text.replace(/^﻿/, '');
  if (!text.trim()) return { exists: true, data: {} }; // an empty file counts as {}
  try {
    const data = JSON.parse(text);
    if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error('not a JSON object');
    return { exists: true, data };
  } catch (e) {
    fail(`${file} is not valid JSON (${e.message}). Nothing was changed. Fix or rename that file and run this again.`);
  }
}

function backup(file) {
  const dest = `${file}.bak-${new Date().toISOString().replace(/[:.]/g, '-')}`;
  say(`backup ${file} -> ${dest}`);
  if (!dry) fs.copyFileSync(file, dest);
}

const same = (a, b) => { const x = path.resolve(a), y = path.resolve(b); return process.platform === 'win32' ? x.toLowerCase() === y.toLowerCase() : x === y; };
const dirsOf = (settings) => String((settings.env && settings.env.CLAUDE_CODE_PLUGIN_DIRS) || '').split(path.delimiter).filter(Boolean);

// Writes settings.json only if its content changes (backup first).
function saveSettings(before, settings) {
  if (JSON.stringify(before.data) === JSON.stringify(settings)) { say('settings.json already up to date'); return; }
  if (before.exists) backup(settingsFile);
  say(`write ${settingsFile}`);
  // Through a symlink (a dotfiles repo), write the target so the link survives the rename.
  if (!dry) writeAtomic(before.exists ? fs.realpathSync(settingsFile) : settingsFile, JSON.stringify(settings, null, 2) + '\n');
}

function settingsEnv(settings) {
  if (settings.env !== undefined && (!settings.env || typeof settings.env !== 'object' || Array.isArray(settings.env))) fail(`${settingsFile} has an "env" entry that is not an object. Nothing was changed.`);
  return settings.env || {};
}

function run(cmd, args, opts) {
  return spawnSync(cmd, args, { encoding: 'utf8', windowsHide: true, ...opts });
}

// run() without blocking the event loop, so that a kill signal and the lock's heartbeat are served while a step runs.
function runAsync(cmd, args, opts = {}) {
  return new Promise((resolve) => {
    const { timeout, ...spawnOpts } = opts;
    let out = '', err = '', child = null, timer = null, settled = false;
    const done = (r) => { if (settled) return; settled = true; clearTimeout(timer); if (running === child) running = null; resolve({ stdout: out, stderr: err, ...r }); };
    try { child = spawn(cmd, args, { windowsHide: true, ...spawnOpts }); } catch (e) { return done({ status: null, error: e }); }
    running = child;
    if (child.stdout) child.stdout.setEncoding('utf8').on('data', (d) => { out = (out + d).slice(-200_000); });
    if (child.stderr) child.stderr.setEncoding('utf8').on('data', (d) => { err = (err + d).slice(-200_000); });
    child.on('error', (e) => done({ status: null, error: e }));
    child.on('close', (status) => done({ status }));
    if (timeout) timer = setTimeout(() => { try { child.kill(); } catch (_) { /* gone */ } done({ status: null, error: new Error(`timed out after ${timeout / 1000} s`) }); }, timeout);
  });
}

// ---- one install at a time. Two runs at once (two terminals, or the add-on's update next to a manual one) would share
// the staging folder and could leave a mod with files missing. The lock is a file created exclusively; it names the
// owner ({pid, at}). While the install runs, the owner touches the file every 30 s; a lock nothing has touched for 5 minutes
// (a killed run, or a pid that now belongs to another program) or whose owner is gone is stale. A second run waits up to
// 60 s, then gives up. A killed run (Ctrl+C, closing the terminal) releases its lock on the way out.
const sleep = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
